package pe.greenminds.ecomind.community.application.internal.queryservices;
import java.util.List;import org.springframework.stereotype.Service;import pe.greenminds.ecomind.community.application.queryservices.CommunityQueryService;import pe.greenminds.ecomind.community.domain.model.aggregates.*;import pe.greenminds.ecomind.community.domain.model.queries.*;import pe.greenminds.ecomind.community.domain.repositories.*;
@Service public class CommunityQueryServiceImpl implements CommunityQueryService{private final CommunityRepository communities;private final CommunityMembershipRepository memberships;public CommunityQueryServiceImpl(CommunityRepository c,CommunityMembershipRepository m){communities=c;memberships=m;}public List<Community> handle(SearchCommunitiesQuery q){return communities.search(q);}public List<CommunityMembership> handle(GetCommunityMembershipsByUserQuery q){return memberships.findByUserId(q.userId());}public List<CommunityMembership> handle(GetCommunityMembershipsByCommunityQuery q){return memberships.findByCommunityId(q.communityId());}}
